import { run } from './drv.mjs';

const PRE = "{'values_changed': {'root': {'new_value': ";
const MARK = "'MARKER'";

// Returns { ok, old, new, diff, raw }
export function probe(s, asOld = true) {
  const r = asOld ? run(s, 'MARKER') : run('MARKER', s);
  let out = r.out;
  if (r.code !== 0) return { ok: false, err: r.err, code: r.code, raw: out };
  if (out.endsWith('\n')) out = out.slice(0, -1);
  if (out === '{}') return { ok: true, equal: true, raw: out };
  if (!out.startsWith(PRE)) return { ok: false, why: 'no prefix', raw: out };
  let rest = out.slice(PRE.length);
  if (!rest.endsWith('}}}')) return { ok: false, why: 'no suffix', raw: out };
  rest = rest.slice(0, -3);
  let nv, ov, diff = null;
  if (asOld) {
    // new_value is the marker
    const sep = MARK + ", 'old_value': ";
    if (!rest.startsWith(sep)) return { ok: false, why: 'marker mismatch', raw: out };
    nv = MARK;
    ov = rest.slice(sep.length);
  } else {
    // old_value is the marker: rest = <nv>, 'old_value': 'MARKER'[, 'diff': ...]
    const sep = ", 'old_value': " + MARK;
    const i = rest.indexOf(sep);
    if (i < 0) return { ok: false, why: 'marker mismatch2', raw: out };
    nv = rest.slice(0, i);
    ov = MARK;
    const tail = rest.slice(i + sep.length);
    if (tail.startsWith(", 'diff': ")) diff = tail.slice(", 'diff': ".length);
    else if (tail !== '') return { ok: false, why: 'tail ' + JSON.stringify(tail), raw: out };
    return { ok: true, new: nv, old: ov, diff, raw: out };
  }
  // asOld: strip possible trailing diff from ov
  const di = ov.lastIndexOf(", 'diff': ");
  if (di >= 0) {
    // only treat as diff if input contains \n
    if (s.includes('\n')) { diff = ov.slice(di + ", 'diff': ".length); ov = ov.slice(0, di); }
  }
  return { ok: true, new: nv, old: ov, diff, raw: out };
}

