import { probe } from './rp_lib.mjs';

// Tokenize a Python str repr back into (codePoint, form) pairs.
export function tokenize(repr) {
  const q = repr[0];
  if (q !== "'" && q !== '"') throw new Error('bad quote: ' + JSON.stringify(repr.slice(0, 20)));
  if (repr[repr.length - 1] !== q) throw new Error('bad close quote');
  const body = repr.slice(1, -1);
  const out = [];
  let i = 0;
  while (i < body.length) {
    const c = body[i];
    if (c === '\\') {
      const n = body[i + 1];
      if (n === 't') { out.push([9, 'special:\\t']); i += 2; }
      else if (n === 'n') { out.push([10, 'special:\\n']); i += 2; }
      else if (n === 'r') { out.push([13, 'special:\\r']); i += 2; }
      else if (n === '\\') { out.push([92, 'special:\\\\']); i += 2; }
      else if (n === q) { out.push([q.codePointAt(0), 'quote-esc']); i += 2; }
      else if (n === 'x') { out.push([parseInt(body.substr(i + 2, 2), 16), 'x']); i += 4; }
      else if (n === 'u') { out.push([parseInt(body.substr(i + 2, 4), 16), 'u']); i += 6; }
      else if (n === 'U') { out.push([parseInt(body.substr(i + 2, 8), 16), 'U']); i += 10; }
      else throw new Error('unknown escape \\' + n);
    } else {
      const cp = body.codePointAt(i);
      out.push([cp, 'literal']);
      i += cp > 0xffff ? 2 : 1;
    }
  }
  return { quote: q, tokens: out };
}

const NONPRINT = /\p{Cc}|\p{Cf}|\p{Cs}|\p{Co}|\p{Cn}|\p{Zl}|\p{Zp}|\p{Zs}/u;
function jsPredictEscaped(cp) {
  if (cp === 0x20) return false;
  return NONPRINT.test(String.fromCodePoint(cp));
}
function jsPredictForm(cp) {
  if (cp === 9) return 'special:\\t';
  if (cp === 10) return 'special:\\n';
  if (cp === 13) return 'special:\\r';
  if (cp === 92) return 'special:\\\\';
  if (!jsPredictEscaped(cp)) return 'literal';
  if (cp < 0x100) return 'x';
  if (cp < 0x10000) return 'u';
  return 'U';
}

const mismatches = [];
let checked = 0;
const quotesSeen = new Set();

function runChunk(cps) {
  const s = String.fromCodePoint(...cps);
  const p = probe(s, true);
  if (!p.ok) { console.log('FAIL chunk', cps[0].toString(16), JSON.stringify(p).slice(0, 200)); return; }
  let t;
  try { t = tokenize(p.old); } catch (e) { console.log('TOKFAIL', cps[0].toString(16), e.message); return; }
  quotesSeen.add(t.quote);
  if (t.tokens.length !== cps.length) {
    console.log('LEN MISMATCH chunk', cps[0].toString(16), t.tokens.length, 'vs', cps.length);
  }
  const n = Math.min(t.tokens.length, cps.length);
  for (let k = 0; k < n; k++) {
    const [cp, form] = t.tokens[k];
    if (cp !== cps[k]) { console.log('CP MISALIGN at', k, cp.toString(16), 'expected', cps[k].toString(16)); break; }
    checked++;
    let expect = jsPredictForm(cp);
    if (form === 'quote-esc') expect = 'quote-esc'; // quote handled separately
    if (form !== expect) mismatches.push([cp, form, expect]);
  }
}

// Build code point list: 0x01..0x10FFFF, skip 0x0A (adds diff key) and surrogates.
const all = [];
for (let cp = 1; cp <= 0x10ffff; cp++) {
  if (cp === 0x0a) continue;
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  all.push(cp);
}
const CHUNK = 14000;
for (let i = 0; i < all.length; i += CHUNK) runChunk(all.slice(i, i + CHUNK));

console.log('checked code points:', checked);
console.log('quotes seen:', [...quotesSeen]);
console.log('mismatches vs Node Unicode data:', mismatches.length);
// collapse into ranges
const rng = [];
for (const [cp, got, exp] of mismatches) {
  const last = rng[rng.length - 1];
  if (last && last.got === got && last.exp === exp && cp === last.hi + 1) last.hi = cp;
  else rng.push({ lo: cp, hi: cp, got, exp });
}
for (const r of rng) {
  console.log('  U+' + r.lo.toString(16).toUpperCase() + '..U+' + r.hi.toString(16).toUpperCase(),
    '(' + (r.hi - r.lo + 1) + ')', 'python=' + r.got, 'node-predicted=' + r.exp);
}
console.log('mismatch ranges:', rng.length);

import { probe } from './rp_lib.mjs';
import { tokenize } from './rp_full.mjs';
import { writeFileSync } from 'node:fs';

console.log('node', process.version, 'unicode', process.versions.unicode);

const NONPRINT = /\p{Cc}|\p{Cf}|\p{Cs}|\p{Co}|\p{Cn}|\p{Zl}|\p{Zp}|\p{Zs}/u;
// Delta: assigned in Unicode 15.1 but NOT in 15.0 (what the bundled CPython uses)
function inDelta(cp) {
  return (cp >= 0x2ffc && cp <= 0x2fff) || cp === 0x31ef || (cp >= 0x2ebf0 && cp <= 0x2ee5d);
}
function escaped(cp) {
  if (cp === 0x20) return false;
  return NONPRINT.test(String.fromCodePoint(cp)) || inDelta(cp);
}
function form(cp) {
  if (cp === 9) return 'special:\\t';
  if (cp === 10) return 'special:\\n';
  if (cp === 13) return 'special:\\r';
  if (cp === 92) return 'special:\\\\';
  if (!escaped(cp)) return 'literal';
  if (cp < 0x100) return 'x';
  if (cp < 0x10000) return 'u';
  return 'U';
}

let checked = 0, bad = 0;
