  const p = probe(String.fromCodePoint(...cps), true);
  if (!p.ok) { console.log('FAIL', cps[0].toString(16)); return; }
  const t = tokenize(p.old);
  for (let k = 0; k < cps.length; k++) {
    const [cp, f] = t.tokens[k];
    if (cp !== cps[k]) { console.log('MISALIGN', k); return; }
    checked++;
    const exp = f === 'quote-esc' ? 'quote-esc' : form(cp);
    if (f !== exp) { bad++; if (badList.length < 40) badList.push([cp.toString(16), f, exp]); }
  }
}

const all = [];
for (let cp = 1; cp <= 0x10ffff; cp++) {
  if (cp === 0x0a) continue;
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  all.push(cp);
}
for (let i = 0; i < all.length; i += 14000) runChunk(all.slice(i, i + 14000));
console.log('checked', checked, 'mismatches', bad, JSON.stringify(badList));

// Emit ground-truth escaped ranges (0x00..0x10FFFF) for the implementer.
const ranges = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
  const e = (cp >= 0xd800 && cp <= 0xdfff) ? true : escaped(cp);
  if (!e) continue;
  const last = ranges[ranges.length - 1];
  if (last && last[1] === cp - 1) last[1] = cp; else ranges.push([cp, cp]);
}
